import org.junit.Test;
import org.junit.Assert;
import org.jfree.chart.imagemap.StandardToolTipTagFragmentGenerator;

public class StandardToolTipTagFragmentGeneratorTest {

    private StandardToolTipTagFragmentGenerator generator;

    @Test
    public void testGenerateToolTipFragment_NormalText() {
        generator = new StandardToolTipTagFragmentGenerator();
        String input = "Hello World";
        String expected = " title=\"Hello World\" alt=\"\"";
        Assert.assertEquals("Should generate correct fragment for normal text", expected, generator.generateToolTipFragment(input));
    }

    @Test
    public void testGenerateToolTipFragment_HtmlCharacters() {
        generator = new StandardToolTipTagFragmentGenerator();
        // Testing htmlEscape functionality via the fragment generator
        String input = "Test < > & \" '";
        // Assuming ImageMapUtilities.htmlEscape converts < to &lt;, > to &gt;, & to &amp;, " to &quot;, ' to &#39;
        String result = generator.generateToolTipFragment(input);

        Assert.assertTrue("Result should contain escaped characters", result.contains("&lt;"));
        Assert.assertTrue("Result should contain escaped characters", result.contains("&gt;"));
        Assert.assertTrue("Result should contain escaped characters", result.contains("&amp;"));
        Assert.assertTrue("Result should contain escaped characters", result.contains("&quot;"));
    }

    @Test
    public void testGenerateToolTipFragment_EmptyString() {
        generator = new StandardToolTipTagFragmentGenerator();
        String input = "";
        String expected = " title=\"\" alt=\"\"";
        Assert.assertEquals("Should handle empty string correctly", expected, generator.generateToolTipFragment(input));
    }

    @Test(expected = NullPointerException.class)
    public void testGenerateToolTipFragment_NullInput() {
        generator = new StandardToolTipTagFragmentGenerator();
        // This tests the behavior when toolTipText is null, 
        // which should trigger a NullPointerException inside ImageMapUtilities.htmlEscape
        generator.generateToolTipFragment(null);
    }
}
