import org.mockito.ArgumentCaptor;

public class BorderArrangementTest {

    private BorderArrangement arrangement;
    private BlockContainer container;
    private Graphics2D g2;
    private RectangleConstraint constraint;

    @Before
    public void setUp() {
        arrangement = new BorderArrangement();
        container = mock(BlockContainer.class);
        g2 = mock(Graphics2D.class);
        constraint = new RectangleConstraint(100.0, 100.0);
    }

    // Helper to access protected method via a subclass
    private class TestBorderArrangement extends BorderArrangement {
        @Override
        public Size2D arrange(BlockContainer container, Graphics2D g2, RectangleConstraint constraint) {
            // The public arrange method usually calls arrangeFF internally
            return super.arrange(container, g2, constraint);
        }

        public Size2D callArrangeFF(BlockContainer container, Graphics2D g2, RectangleConstraint constraint) {
            return super.arrangeFF(container, g2, constraint);
        }
    }

    private TestBorderArrangement testArrangement;

    @Before
    public void initTestArrangement() {
        testArrangement = new TestBorderArrangement();
    }

    @Test
    public void testArrangeFF_AllBlocksPresent() {
        Block top = mock(Block.class);
        Block bottom = mock(Block.class);
        Block left = mock(Block.class);
        Block right = mock(Block.class);
        Block center = mock(Block.class);

        // Setup mocks to return specific sizes
        when(top.arrange(any(Graphics2D.class), any(RectangleConstraint.class))).thenReturn(new Size2D(100.0, 20.0));
        when(bottom.arrange(any(Graphics2D.class), any(RectangleConstraint.class))).thenReturn(new Size2D(100.0, 20.0));
        when(left.arrange(any(Graphics2D.class), any(RectangleConstraint.class))).thenReturn(new Size2D(20.0, 60.0));
        when(right.arrange(any(Graphics2D.class), any(RectangleConstraint.class))).thenReturn(new Size2D(20.0, 60.0));
        when(center.arrange(any(Graphics2D.class), any(RectangleConstraint.class))).thenReturn(new Size2D(60.0, 60.0));

        // Use reflection or the subclass helper to set private fields
        setPrivateField(testArrangement, "topBlock", top);
        setPrivateField(testArrangement, "bottomBlock", bottom);
        setPrivateField(testArrangement, "leftBlock", left);
        setPrivateField(testArrangement, "rightBlock", right);
        setPrivateField(testArrangement, "centerBlock", center);

        Size2D result = testArrangement.callArrangeFF(container, g2, constraint);

        assertEquals(100.0, result.width, 0.001);
        assertEquals(100.0, result.height, 0.001);

        // Verify bounds
        ArgumentCaptor<Rectangle2D> rectCaptor = ArgumentCaptor.forClass(Rectangle2D.class);
        verify(top).setBounds(rectCaptor.capture());
        assertEquals(0.0, rectCaptor.getValue().getX(), 0.001);
        assertEquals(0.0, rectCaptor.getValue().getY(), 0.001);
        assertEquals(100.0, rectCaptor.getValue().getWidth(), 0.001);
        assertEquals(20.0, rectCaptor.getValue().getHeight(), 0.001);

        verify(bottom).setBounds(rectCaptor.capture());
        assertEquals(0.0, rectCaptor.getValue().getX(), 0.001);
        assertEquals(80.0, rectCaptor.getValue().getY(), 0.001); // h[0] + h[2] = 20 + 60

        verify(left).setBounds(rectCaptor.capture());
        assertEquals(0.0, rectCaptor.getValue().getX(), 0.001);
        assertEquals(20.0, rectCaptor.getValue().getY(), 0.001);
        assertEquals(20.0, rectCaptor.getValue().getWidth(), 0.001);

        verify(right).setBounds(rectCaptor.capture());
        assertEquals(80.0, rectCaptor.getValue().getX(), 0.001); // w[2] + w[4] = 20 + 60
        assertEquals(20.0, rectCaptor.getValue().getY(), 0.001);

        verify(center).setBounds(rectCaptor.capture());
        assertEquals(20.0, rectCaptor.getValue().getX(), 0.001);
        assertEquals(20.0, rectCaptor.getValue().getY(), 0.001);
        assertEquals(60.0, rectCaptor.getValue().getWidth(), 0.001);
    }

    @Test
    public void testArrangeFF_NoBlocksPresent() {
        // All blocks are null
        Size2D result = testArrangement.callArrangeFF(container, g2, constraint);
        assertEquals(100.0, result.width, 0.001);
        assertEquals(100.0, result.height, 0.001);
    }

    @Test
    public void testArrangeFF_OnlyCenterBlock() {
        Block center = mock(Block.class);
        setPrivateField(testArrangement, "centerBlock", center);

        testArrangement.callArrangeFF(container, g2, constraint);

        ArgumentCaptor<Rectangle2D> rectCaptor = ArgumentCaptor.forClass(Rectangle2D.class);
        verify(center).setBounds(rectCaptor.capture());
        assertEquals(0.0, rectCaptor.getValue().getX(), 0.001);
        assertEquals(0.0, rectCaptor.getValue().getY(), 0.001);
        assertEquals(100.0, rectCaptor.getValue().getWidth(), 0.001);
        assertEquals(100.0, rectCaptor.getValue().getHeight(), 0.001);
    }

    @Test
    public void testArrangeFF_NegativeWidthHandling() {
        // Force a scenario where constraint.getWidth() - w[2] is negative
        Block left = mock(Block.class);
        when(left.arrange(any(Graphics2D.class), any(RectangleConstraint.class))).thenReturn(new Size2D(150.0, 10.0));
        setPrivateField(testArrangement, "leftBlock", left);

        Block right = mock(Block.class);
        setPrivateField(testArrangement, "rightBlock", right);

        // This should trigger Math.max(constraint.getWidth() - w[2], 0.0)
        testArrangement.callArrangeFF(container, g2, constraint);

        ArgumentCaptor<RectangleConstraint> constraintCaptor = ArgumentCaptor.forClass(RectangleConstraint.class);
        verify(right).arrange(eq(g2), constraintCaptor.capture());
        // Range should be (0.0, 0.0) because 100 - 150 < 0
        assertEquals(0.0, constraintCaptor.getValue().getWidthRange().getLower(), 0.001);
        assertEquals(0.0, constraintCaptor.getValue().getWidthRange().getUpper(), 0.001);
    }

    private void setPrivateField(Object target, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
