    public void testRemoveRangeMarkerForegroundSuccess() {
        // Create a marker and add it to the foreground layer
        Marker marker = new ValueMarker(10.0, Color.RED, new BasicStroke(1.0f), Color.BLUE, new BasicStroke(1.0f), 0.5f);
        plot.addRangeMarker(marker, Layer.FOREGROUND);

        // Verify it exists in foreground
        Collection markers = plot.getRangeMarkers(Layer.FOREGROUND);
        Assert.assertTrue("Marker should be in foreground", markers.contains(marker));

        // Test the method under test
        boolean result = plot.removeRangeMarker(marker);

        Assert.assertTrue("removeRangeMarker should return true when marker is removed", result);
        Collection afterMarkers = plot.getRangeMarkers(Layer.FOREGROUND);
        Assert.assertFalse("Marker should have been removed from foreground", afterMarkers.contains(marker));
    }

    @Test
    public void testRemoveRangeMarkerForegroundFailure() {
        // Create a marker but do NOT add it to the plot
        Marker marker = new ValueMarker(10.0, Color.RED, new BasicStroke(1.0f), Color.BLUE, new BasicStroke(1.0f), 0.5f);

        // Test the method under test
        boolean result = plot.removeRangeMarker(marker);

        Assert.assertFalse("removeRangeMarker should return false when marker is not present", result);
    }

    @Test
    public void testRemoveRangeMarkerWrongLayer() {
        // Create a marker and add it to the BACKGROUND layer
        Marker marker = new ValueMarker(10.0, Color.RED, new BasicStroke(1.0f), Color.BLUE, new BasicStroke(1.0f), 0.5f);
        plot.addRangeMarker(marker, Layer.BACKGROUND);

        // Verify it exists in background
        Collection backgroundMarkers = plot.getRangeMarkers(Layer.BACKGROUND);
        Assert.assertTrue("Marker should be in background", backgroundMarkers.contains(marker));

        // The method removeRangeMarker(marker) calls removeRangeMarker(marker, Layer.FOREGROUND)
        boolean result = plot.removeRangeMarker(marker);

        Assert.assertFalse("removeRangeMarker should return false if marker is in BACKGROUND but searched in FOREGROUND", result);

        // Verify it still exists in background
        Collection afterBackgroundMarkers = plot.getRangeMarkers(Layer.BACKGROUND);
        Assert.assertTrue("Marker should still be in background", afterBackgroundMarkers.contains(marker));
    }

    @Test
    public void testRemoveRangeMarkerNull() {
        // Test with null marker
        boolean result = plot.removeRangeMarker(null);
        Assert.assertFalse("removeRangeMarker should return false when marker is null", result);
    }

    @Test
    public void testRemoveDefaultBaselineMarker() {
        // The constructor adds a baseline marker to the BACKGROUND layer.
        // Since removeRangeMarker(marker) targets FOREGROUND, we need to find the baseline marker first.
        Collection backgroundMarkers = plot.getRangeMarkers(Layer.BACKGROUND);
        Marker baseline = null;
        for (Object m : backgroundMarkers) {
            if (m instanceof Marker) {
                baseline = (Marker) m;
                break;
            }
        }

        Assert.assertNotNull("Baseline marker should exist in background", baseline);

        // Attempt to remove it using the foreground method
        boolean result = plot.removeRangeMarker(baseline);
        Assert.assertFalse("Should return false because baseline is in BACKGROUND, not FOREGROUND", result);
    }
}
