import org.junit.Test;
import org.junit.Assert;
import org.jfree.data.time.TimeSeries;
import org.jfree.data.time.Day;
import org.jfree.data.time.TimeSeriesDataItem;
import org.jfree.data.time.RegularTimePeriod;
import java.util.List;

public class TimeSeriesTest {

    @Test
    public void testCloneBasic() throws CloneNotSupportedException {
        TimeSeries original = new TimeSeries("Test Series");
        original.setDomainDescription("Custom Domain");
        original.setRangeDescription("Custom Range");

        // Add some data to test deep cloning of the list
        Day day1 = new Day(1, 1, 2023);
        original.add(day1, 10.5);
        Day day2 = new Day(2, 1, 2023);
        original.add(day2, 20.5);

        TimeSeries cloned = (TimeSeries) original.clone();

        // Verify basic properties are copied (shallow copy via super.clone())
        Assert.assertEquals("Name should be the same", original.getDatasetName(), cloned.getDatasetName());
        Assert.assertEquals("Domain description should be the same", original.getDomainDescription(), cloned.getDomainDescription());
        Assert.assertEquals("Range description should be the same", original.getRangeDescription(), cloned.getRangeDescription());
        Assert.assertEquals("Time period class should be the same", original.getTimePeriodClass(), cloned.getTimePeriodClass());

        // Verify data list is cloned (deep copy)
        Assert.assertEquals("Item count should be the same", original.getItemCount(), cloned.getItemCount());
        Assert.assertNotSame("Data list should be a different instance", original.getItems(), cloned.getItems());

        // Verify content of the data list
        for (int i = 0; i < original.getItemCount(); i++) {
            TimeSeriesDataItem originalItem = original.getDataItem(i);
            TimeSeriesDataItem clonedItem = cloned.getDataItem(i);
            Assert.assertEquals("Period should be the same", originalItem.getPeriod(), clonedItem.getPeriod());
            Assert.assertEquals("Value should be the same", originalItem.getValue(), clonedItem.getValue());
        }
    }

    @Test
    public void testCloneDeepCopyIndependence() throws CloneNotSupportedException {
        TimeSeries original = new TimeSeries("Independence Test");
        Day day = new Day(1, 1, 2023);
        original.add(day, 100.0);

        TimeSeries cloned = (TimeSeries) original.clone();

        // Modify the cloned series
        cloned.add(new Day(2, 1, 2023), 200.0);
        cloned.setDomainDescription("Modified Domain");

        // Verify original remains unchanged
        Assert.assertEquals("Original item count should remain 1", 1, original.getItemCount());
        Assert.assertEquals("Original domain description should remain unchanged", "Time", original.getDomainDescription());

        // Verify cloned series has the changes
        Assert.assertEquals("Cloned item count should be 2", 2, cloned.getItemCount());
        Assert.assertEquals("Cloned domain description should be updated", "Modified Domain", cloned.getDomainDescription());
    }

    @Test
    public void testCloneEmptySeries() throws CloneNotSupportedException {
        TimeSeries original = new TimeSeries("Empty Series", Day.class);
        TimeSeries cloned = (TimeSeries) original.clone();

        Assert.assertEquals("Cloned series should be empty", 0, cloned.getItemCount());
        Assert.assertNotNull("Cloned data list should not be null", cloned.getItems());
        Assert.assertNotSame("Data list should be a different instance even if empty", original.getItems(), cloned.getItems());
    }

    @Test
    public void testCloneWithCustomConstructor() throws CloneNotSupportedException {
        TimeSeries original = new TimeSeries("Custom", "X-Axis", "Y-Axis", Day.class);
        TimeSeries cloned = (TimeSeries) original.clone();

        Assert.assertEquals("X-Axis", cloned.getDomainDescription());
        Assert.assertEquals("Y-Axis", cloned.getRangeDescription());
        Assert.assertEquals(Day.class, cloned.getTimePeriodClass());
    }
}
