public class DefaultKeyedValues2DTest {

    private DefaultKeyedValues2D dataset;

    @Rule
    public ExpectedException thrown = ExpectedException.none();

    @Before
    public void setUp() {
        dataset = new DefaultKeyedValues2D();
    }

    @Test
    public void testRemoveColumnNullKey() {
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("Null 'columnKey' argument.");
        dataset.removeColumn(null);
    }

    @Test
    public void testRemoveColumnUnknownKey() {
        dataset.addValue(1.0, "Row1", "Col1");

        thrown.expect(UnknownKeyException.class);
        thrown.expectMessage("Unknown key: Col2");
        dataset.removeColumn("Col2");
    }

    @Test
    public void testRemoveColumnSuccess() {
        // Setup data
        dataset.addValue(1.0, "Row1", "Col1");
        dataset.addValue(2.0, "Row1", "Col2");
        dataset.addValue(3.0, "Row2", "Col1");
        dataset.addValue(4.0, "Row2", "Col2");

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals(2, dataset.getRowCount());
        assertEquals(1.0, dataset.getValue("Row1", "Col1").doubleValue(), 0.001);
        assertEquals(2.0, dataset.getValue("Row1", "Col2").doubleValue(), 0.001);

        // Execute removal
        dataset.removeColumn("Col1");

        // Verify column count decreased
        assertEquals(1, dataset.getColumnCount());

        // Verify the specific column key is gone
        assertEquals(-1, dataset.getColumnIndex("Col1"));

        // Verify values for the removed column are gone (should return null or throw depending on implementation)
        assertNull("Value for removed column should be null", dataset.getValue("Row1", "Col1"));

        // Verify other columns are still intact
        assertEquals(2.0, dataset.getValue("Row1", "Col2").doubleValue(), 0.001);
    }

    @Test
    public void testRemoveColumnWithPartialData() {
        // Setup data where some rows don't have the column being removed
        dataset.addValue(1.0, "Row1", "Col1");
        dataset.addValue(2.0, "Row1", "Col2");
        // Row2 only has Col2
        dataset.addValue(3.0, "Row2", "Col2");

        // Remove Col1
        dataset.removeColumn("Col1");

        assertEquals(1, dataset.getColumnCount());
        assertNull(dataset.getValue("Row1", "Col1"));
        assertEquals(2.0, dataset.getValue("Row1", "Col2").doubleValue(), 0.001);
        assertEquals(3.0, dataset.getValue("Row2", "Col2").doubleValue(), 0.001);
    }

    @Test
    public void testRemoveLastColumn() {
        dataset.addValue(1.0, "Row1", "Col1");
        dataset.removeColumn("Col1");
        assertEquals(0, dataset.getColumnCount());
    }
}

