    @Before
    public void setUp() {
        dataset = new DefaultBoxAndWhiskerCategoryDataset();
    }

    /**
     * Helper method to invoke the private updateBounds method via reflection
     */
    private void invokeUpdateBounds() throws Exception {
        Method method = DefaultBoxAndWhiskerCategoryDataset.class.getDeclaredMethod("updateBounds");
        method.setAccessible(true);
        method.invoke(dataset);
    }

    /**
     * Helper method to get private field values for verification
     */
    private Object getPrivateField(String fieldName) throws Exception {
        Field field = DefaultBoxAndWhiskerCategoryDataset.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(dataset);
    }

    @Test
    public void testUpdateBoundsEmptyDataset() throws Exception {
        invokeUpdateBounds();
        Assert.assertTrue(Double.isNaN((Double) getPrivateField("minimumRangeValue")));
        Assert.assertEquals(-1, (Integer) getPrivateField("minimumRangeValueRow"));
        Assert.assertEquals(-1, (Integer) getPrivateField("minimumRangeValueColumn"));
        Assert.assertTrue(Double.isNaN((Double) getPrivateField("maximumRangeValue")));
        Assert.assertEquals(-1, (Integer) getPrivateField("maximumRangeValueRow"));
        Assert.assertEquals(-1, (Integer) getPrivateField("maximumRangeValueColumn"));
    }

    @Test
    public void testUpdateBoundsWithValidValues() throws Exception {
        // Item 1: Min 10.0, Max 20.0
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(10.0, 15.0, 15.0, 15.0, 20.0, new Double[]{10.0, 20.0});
        // Item 2: Min 5.0, Max 25.0
        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(5.0, 12.0, 12.0, 12.0, 22.0, new Double[]{5.0, 25.0});

        dataset.add(item1, "Row0", "Col0");
        dataset.add(item2, "Row1", "Col1");

        invokeUpdateBounds();

        Assert.assertEquals(5.0, (Double) getPrivateField("minimumRangeValue"), 0.001);
        Assert.assertEquals(1, (Integer) getPrivateField("minimumRangeValueRow"));
        Assert.assertEquals(1, (Integer) getPrivateField("minimumRangeValueColumn"));
        Assert.assertEquals(25.0, (Double) getPrivateField("maximumRangeValue"), 0.001);
        Assert.assertEquals(1, (Integer) getPrivateField("maximumRangeValueRow"));
        Assert.assertEquals(1, (Integer) getPrivateField("maximumRangeValueColumn"));
    }

    @Test
    public void testUpdateBoundsWithNullItemsAndNaNs() throws Exception {
        // Create a custom item to simulate null outliers or NaNs
        // Since BoxAndWhiskerItem might not allow nulls in constructor, 
        // we use a subclass or mock if necessary, but here we test the logic paths.

        // Item with NaN outliers
        BoxAndWhiskerItem itemNaN = new BoxAndWhiskerItem(Double.NaN, 10.0, 10.0, 10.0, Double.NaN, new Double[]{Double.NaN, Double.NaN});
        dataset.add(itemNaN, "Row0", "Col0");

        invokeUpdateBounds();

        Assert.assertTrue("Should remain NaN when only NaNs are present", 
