    }

    @Test
    public void testUpdateBoundsWithMixedNulls() throws Exception {
        // We need to ensure the 'if (item != null)' and 'if (min != null)' branches are hit.
        // DefaultBoxAndWhiskerCategoryDataset.add doesn't allow null items, 
        // but we can test the logic by adding items with specific outlier values.

        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(10.0, 11.0, 12.0, 13.0, 14.0, new Double[]{10.0, 14.0});
